function RingtonePreview({ active, onToggle }: { active: boolean; onToggle: () => void }) {
  const ctxRef = useRef<AudioContext | null>(null)
  const timerRef = useRef<number | null>(null)
  const playTone = () => {
    const AudioCtx = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!AudioCtx) return
    const ctx = ctxRef.current || new AudioCtx(); ctxRef.current = ctx
    const now = ctx.currentTime
    ;[523.25, 659.25, 783.99, 659.25].forEach((frequency, index) => {
      const osc = ctx.createOscillator(); const gain = ctx.createGain()
      osc.type = 'sine'; osc.frequency.value = frequency
      gain.gain.setValueAtTime(0.0001, now + index * .18); gain.gain.exponentialRampToValueAtTime(.06, now + index * .18 + .025); gain.gain.exponentialRampToValueAtTime(.0001, now + index * .18 + .16)
      osc.connect(gain).connect(ctx.destination); osc.start(now + index * .18); osc.stop(now + index * .18 + .18)
    })
  }
  useEffect(() => { if (active) { playTone(); timerRef.current = window.setInterval(playTone, 1300) } return () => { if (timerRef.current) window.clearInterval(timerRef.current) } }, [active])
  return <button className={`ringtone-preview ${active ? 'playing' : ''}`} onClick={onToggle}>{active ? <Volume2 size={15} /> : <Play size={15} />} {active ? 'Playing Contak Pulse' : 'Preview Contak Pulse'}</button>
}

function AuthScreen({ onAuthenticated, initialMode = 'login', onBack }: { onAuthenticated: (session: AuthSession) => void; initialMode?: 'login' | 'register'; onBack?: () => void }) {
  const [mode, setMode] = useState<'login' | 'register'>(initialMode)
  const [username, setUsername] = useState('')
  const [displayName, setDisplayName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setError(''); setBusy(true)
    try {
      const payload = mode === 'login' ? { username, password } : { username, displayName, email, password }
      const session = await apiRequest<AuthSession>(`/auth/${mode}`, { method: 'POST', body: JSON.stringify(payload) })
      localStorage.setItem('contak-session', JSON.stringify(session)); onAuthenticated(session)
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to connect') } finally { setBusy(false) }
  }
  return <div className="auth-shell"><div className="auth-glow" /><div className="auth-card"><div className="brand auth-brand"><span className="brand-mark" /> <span>Contak<span className="brand-dot">.</span>App</span></div>{onBack && <button className="auth-back" onClick={onBack}><ArrowLeft size={14} /> Back to landing</button>}<p className="eyebrow">Private communication</p><h1>{mode === 'login' ? 'Welcome back' : 'Create your space'}</h1><p className="auth-copy">{mode === 'login' ? 'Sign in to pick up where you left off.' : 'Start a secure, beautifully simple conversation space.'}</p><form onSubmit={submit}>{mode === 'register' && <><label>Display name<input value={displayName} onChange={event => setDisplayName(event.target.value)} required minLength={2} /></label><label>Email<input type="email" value={email} onChange={event => setEmail(event.target.value)} required /></label></>}<label>Username<input value={username} onChange={event => setUsername(event.target.value)} required minLength={3} autoComplete="username" /></label><label>Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} required minLength={8} autoComplete={mode === 'login' ? 'current-password' : 'new-password'} /></label>{error && <p className="form-error">{error}</p>}<button className="primary-btn auth-submit" disabled={busy}>{busy ? 'Connecting...' : mode === 'login' ? 'Enter Contak.App' : 'Create account'}<ChevronDown size={16} className="auth-arrow" /></button></form><button className="auth-switch" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError('') }}>{mode === 'login' ? 'Need an account? Create one' : 'Already have an account? Sign in'}</button><div className="auth-note"><ShieldCheck size={15} /> Your messages are protected by your private workspace.</div></div></div>
}

