function ViewOnceAttachment({ message, token }: { message: Message; token: string }) {
  const attachment = message.attachment
  const [state, setState] = useState(attachment?.ephemeral?.state || 'unopened')
  const [busy, setBusy] = useState(false)
  const [viewer, setViewer] = useState('')
  const [error, setError] = useState('')
  const claim = async () => {
    if (!message.conversationId || !attachment || busy || state !== 'unopened') return
    setBusy(true); setError('')
    try {
      const claimed = await apiRequest<{ sessionToken: string; contentPath: string; durationSeconds: number }>(`/conversations/${message.conversationId}/view-once/${message.id}/claim`, { method: 'POST' }, token)
      const response = await fetch(claimed.contentPath, { headers: { Authorization: `Bearer ${token}`, 'X-View-Once-Session': claimed.sessionToken }, cache: 'no-store' })
      if (!response.ok) throw new Error('This View Once photo is no longer available')
      const blob = await response.blob(); const url = URL.createObjectURL(blob); setViewer(url); setState('viewing')
      if (claimed.durationSeconds > 0) window.setTimeout(() => { setViewer(current => { if (current) URL.revokeObjectURL(current); return '' }); void apiRequest(`/conversations/${message.conversationId}/view-once/${message.id}/close`, { method: 'POST', body: JSON.stringify({ sessionToken: claimed.sessionToken }) }, token).catch(() => undefined); setState('opened') }, claimed.durationSeconds * 1000)
      ;(window as typeof window & { __contakViewOnce?: { token: string } }).__contakViewOnce = { token: claimed.sessionToken }
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'This View Once photo is no longer available'); setState('expired') } finally { setBusy(false) }
  }
  const close = () => {
    const session = (window as typeof window & { __contakViewOnce?: { token: string } }).__contakViewOnce
    if (viewer) URL.revokeObjectURL(viewer)
    setViewer(''); setState('opened')
    if (session && message.conversationId) void apiRequest(`/conversations/${message.conversationId}/view-once/${message.id}/close`, { method: 'POST', body: JSON.stringify({ sessionToken: session.token }) }, token).catch(() => undefined)
    delete (window as typeof window & { __contakViewOnce?: unknown }).__contakViewOnce
  }
  if (viewer) return <div className="view-once-viewer" role="dialog" aria-modal="true"><button className="view-once-close" onClick={close} aria-label="Close View Once photo"><X size={22} /></button><img src={viewer} alt="View Once photo" draggable={false} /><div className="view-once-warning"><EyeOff size={16} /> View Once photo · do not save or share</div></div>
  if (message.from === 'me') return <div className="view-once-status"><EyeOff size={18} /><span>{state === 'opened' ? 'Opened' : state === 'expired' ? 'Expired' : 'View Once photo'}<small>{state === 'unopened' ? 'Not opened yet' : state === 'opened' ? 'Opened once' : 'No longer available'}</small></span></div>
  return <button className="view-once-bubble" onClick={() => void claim()} disabled={busy || state !== 'unopened'}><EyeOff size={22} /><span>{busy ? 'Opening securely...' : state === 'expired' ? 'Expired' : state === 'opened' ? 'Opened' : 'Tap to view once'}<small>{error || 'This photo can be viewed only once.'}</small></span></button>
}

function AttachmentPreview({ message, token }: { message: Message; token: string }) {
  const [source, setSource] = useState('')
  const attachment = message.attachment
  useEffect(() => {
    if (!attachment || attachment.ephemeral || !attachment.url) return
    let active = true
    let objectUrl = ''
    if (!attachment.url) return
    fetch(attachment.url, { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' })
      .then(response => { if (!response.ok) throw new Error('Attachment unavailable'); return response.blob() })
      .then(blob => { objectUrl = URL.createObjectURL(blob); if (active) setSource(objectUrl) })
      .catch(() => { if (active) setSource('') })
    return () => { active = false; if (objectUrl) URL.revokeObjectURL(objectUrl) }
  }, [attachment, token])
  if (!attachment) return null
  if (attachment.ephemeral) return <ViewOnceAttachment message={message} token={token} />
  if (!source) return <div className="attachment-loading"><Paperclip size={16} />Loading {attachment.name}...</div>
  if (attachment.mime.startsWith('image/')) return <img className="attachment-image" src={source} alt={attachment.name} />
  if (attachment.mime.startsWith('video/')) return <video className="attachment-video" src={source} controls preload="metadata" />
  return <a className="attachment-file" href={source} download={attachment.name}><FileText size={20} /><span>{attachment.name}<small>{Math.ceil(attachment.size / 1024)} KB</small></span><Download size={16} /></a>
}

function MessageBubble({ message, token }: { message: Message; token: string }) {
  const attachmentMessage = Boolean(message.attachment)
  return <div className={`message-line ${message.from}`}><div className={`message-bubble ${message.text.startsWith('build-') || attachmentMessage ? 'file-message' : ''}`}>
    {message.attachment ? <AttachmentPreview message={message} token={token} /> : message.text.startsWith('build-') && <FileText size={21} />}
    {!message.attachment && <span>{message.text}</span>}
    {message.attachment && <span className="attachment-caption">{message.text}</span>}
    <small>{message.time} {message.from === 'me' && (message.read ? <CheckCheck size={13} /> : <Check size={13} />)}</small>
    {message.reaction && <i className="reaction">{message.reaction}</i>}
  </div></div>
}

function Conversation({ chat, messages, setMessages, onSend, onUpload, token, onTyping, typing, onCall, onBack }: { chat: Chat; messages: Message[]; setMessages: React.Dispatch<React.SetStateAction<Record<string, Message[]>>>; onSend?: (chat: Chat, text: string) => Promise<void>; onUpload?: (chat: Chat, file: File, onProgress: (percent: number) => void, options?: UploadOptions) => Promise<void>; token: string; onTyping?: (chat: Chat, typing: boolean) => void; typing: boolean; onCall: (kind: 'audio' | 'video') => void; onBack: () => void }) {
  const [draft, setDraft] = useState('')
  const [attachmentMenuOpen, setAttachmentMenuOpen] = useState(false)
  const [emojiOpen, setEmojiOpen] = useState(false)
  const [optionsOpen, setOptionsOpen] = useState(false)
  const [detailsOpen, setDetailsOpen] = useState(false)
  const [searchOpen, setSearchOpen] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [muted, setMuted] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState(0)
  const [uploadName, setUploadName] = useState('')
  const [composerError, setComposerError] = useState('')
  const [pendingFile, setPendingFile] = useState<File | null>(null)
  const [pendingPreview, setPendingPreview] = useState('')
  const [viewOnceIntent, setViewOnceIntent] = useState(false)
  const [viewDurationSeconds, setViewDurationSeconds] = useState(0)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const endRef = useRef<HTMLDivElement>(null)
  const quickEmojis = ['😀', '😂', '😍', '👍', '👏', '🔥', '🎉', '❤️', '🙏', '😎', '🤔', '✅']
  useEffect(() => { endRef.current?.scrollIntoView({ behavior: 'smooth' }) }, [messages.length, typing])
  const send = async () => { const value = draft.trim(); if (!value) return; setDraft(''); setComposerError(''); onTyping?.(chat, false); if (onSend) { await onSend(chat, value); return }; setMessages(prev => ({ ...prev, [chat.id]: [...(prev[chat.id] || []), { id: Date.now(), from: 'me', text: value, time: 'Now', read: false }] })) }
  const openPicker = (accept: string, enableViewOnce = false) => { if (!fileInputRef.current) return; setViewOnceIntent(enableViewOnce); fileInputRef.current.accept = accept; fileInputRef.current.click(); setAttachmentMenuOpen(false); setEmojiOpen(false) }
  const handleFile = async (file?: File) => { if (!file || !onUpload) return; if (file.type.startsWith('image/')) { setPendingFile(file); setPendingPreview(URL.createObjectURL(file)); return }; await sendFile(file, {}) }
  const sendFile = async (file: File, options: UploadOptions) => { if (!onUpload) return; setUploading(true); setUploadProgress(0); setUploadName(file.name); setComposerError(''); try { await onUpload(chat, file, setUploadProgress, options); if (pendingPreview) URL.revokeObjectURL(pendingPreview); setPendingFile(null); setPendingPreview(''); setViewOnceIntent(false) } catch (reason) { setComposerError(reason instanceof Error ? reason.message : 'Unable to upload attachment') } finally { setUploading(false); setUploadName(''); if (fileInputRef.current) fileInputRef.current.value = '' } }
  const visibleMessages = searchQuery.trim() ? messages.filter(message => `${message.text} ${message.attachment?.name || ''}`.toLowerCase().includes(searchQuery.trim().toLowerCase())) : messages
  return <main className="conversation">
    <header className="conversation-header"><div className="conversation-person"><button className="conversation-back icon-btn" onClick={onBack} aria-label="Back to contacts"><ArrowLeft size={18} /></button><Avatar chat={chat} /><div><h2>{chat.name}</h2><p><span className="status-dot" /> {chat.status === 'online' ? 'Online' : chat.status === 'away' ? 'Away' : 'Offline'}{muted && <span className="muted-label"> · Muted</span>}</p></div></div><div className="conversation-actions"><button onClick={() => onCall('audio')} className="icon-btn" aria-label="Audio call"><Phone size={18} /></button><button onClick={() => onCall('video')} className="icon-btn" aria-label="Video call"><Video size={18} /></button><button className="icon-btn desktop-only" onClick={() => setSearchOpen(value => !value)} aria-label="Search messages" aria-pressed={searchOpen}><Search size={18} /></button><div className="conversation-menu-wrap"><button className="icon-btn" onClick={() => setOptionsOpen(value => !value)} aria-label="More options" aria-expanded={optionsOpen}><MoreVertical size={18} /></button>{optionsOpen && <div className="conversation-menu"><button onClick={() => { setSearchOpen(true); setOptionsOpen(false) }}><Search size={15} /><span>Search messages</span></button><button onClick={() => { setMuted(value => !value); setOptionsOpen(false) }}><Bell size={15} /><span>{muted ? 'Unmute notifications' : 'Mute notifications'}</span></button><button onClick={() => { setDetailsOpen(value => !value); setOptionsOpen(false) }}><CircleHelp size={15} /><span>Contact details</span></button></div>}{detailsOpen && <div className="contact-details-popover"><strong>{chat.name}</strong><span>{chat.handle}</span><span>{chat.status === 'online' ? 'Online now' : 'Private contact'}</span></div>}</div></div></header>
    {searchOpen && <div className="message-search"><Search size={15} /><input value={searchQuery} onChange={event => setSearchQuery(event.target.value)} placeholder="Search this conversation" aria-label="Search this conversation" /><button onClick={() => { setSearchQuery(''); setSearchOpen(false) }} aria-label="Close message search"><X size={15} /></button></div>}
    <div className="message-scroll"><div className="day-divider"><span>{searchQuery.trim() ? `${visibleMessages.length} result${visibleMessages.length === 1 ? '' : 's'}` : 'Today'}</span></div>{visibleMessages.map(message => <MessageBubble key={message.id} message={message} token={token} />)}{searchQuery.trim() && !visibleMessages.length && <div className="search-empty"><Search size={20} /><span>No messages match “{searchQuery}”.</span></div>}{typing && !searchQuery.trim() && <div className="typing-row"><Avatar chat={chat} size="sm" /><div className="typing-bubble"><span /><span /><span /></div><small>{chat.name.split(' ')[0]} is typing...</small></div>}<div ref={endRef} /></div>
    <div className="composer-wrap"><div className="composer-shell">{uploading && <div className="upload-progress" aria-live="polite"><div className="upload-progress-copy"><span><Paperclip size={14} /> Sending {uploadName}</span><strong>{uploadProgress}%</strong></div><div className="upload-progress-track"><span style={{ width: `${Math.max(uploadProgress, 3)}%` }} /></div></div>}<div className="composer-popovers">{attachmentMenuOpen && <div className="attachment-menu"><strong>Add to message</strong><button onClick={() => { setEmojiOpen(true); setAttachmentMenuOpen(false) }}><Smile size={17} /><span>Emoji</span></button><button onClick={() => openPicker('image/*')}><Image size={17} /><span>Image</span></button><button onClick={() => openPicker('image/*', true)}><EyeOff size={17} /><span>View Once photo</span></button><button onClick={() => openPicker('image/gif')}><Sparkles size={17} /><span>GIF file</span></button><button onClick={() => openPicker('video/*')}><Video size={17} /><span>Video</span></button><button onClick={() => openPicker('*/*')}><Paperclip size={17} /><span>File</span></button></div>}{emojiOpen && <div className="emoji-menu">{quickEmojis.map(emoji => <button key={emoji} onClick={() => { setDraft(value => `${value}${emoji}`); setEmojiOpen(false); setAttachmentMenuOpen(false) }} aria-label={`Add ${emoji}`}>{emoji}</button>)}</div>}</div><div className="composer"><button className={`composer-icon ${attachmentMenuOpen ? 'active' : ''}`} onClick={() => { setAttachmentMenuOpen(value => !value); setEmojiOpen(false) }} aria-label="Add attachment" aria-expanded={attachmentMenuOpen}><Plus size={20} /></button><input value={draft} onChange={event => { setDraft(event.target.value); setComposerError(''); onTyping?.(chat, event.target.value.length > 0) }} onKeyDown={event => { if (event.key === 'Enter') void send() }} placeholder={uploading ? 'Uploading attachment...' : `Message ${chat.name}...`} aria-label={`Message ${chat.name}`} disabled={uploading} /><button className="composer-icon" onClick={() => { setEmojiOpen(value => !value); setAttachmentMenuOpen(false) }} aria-label="Emoji"><Smile size={19} /></button><button className="send-btn" onClick={() => void send()} aria-label="Send message" disabled={uploading}><Send size={18} /></button></div><input ref={fileInputRef} className="hidden-file-input" type="file" onChange={event => void handleFile(event.target.files?.[0])} />{composerError && <p className="composer-error">{composerError}</p>}</div><div className="composer-meta"><span><ShieldCheck size={12} /> Private conversation</span><span>Enter to send</span></div></div>
    {pendingFile && pendingPreview && <div className="attachment-preview-modal" role="dialog" aria-modal="true"><div className="attachment-preview-card"><button className="icon-btn" onClick={() => { URL.revokeObjectURL(pendingPreview); setPendingFile(null); setPendingPreview(''); setViewOnceIntent(false) }} aria-label="Cancel attachment"><X size={18} /></button><img src={pendingPreview} alt="Attachment preview" /><div className="view-once-toggle-row"><div><strong>View Once photo</strong><span>{viewOnceIntent ? 'Recipient can open it only once.' : 'Send as a regular photo.'}</span></div><button className={`visibility-switch ${viewOnceIntent ? 'on' : ''}`} onClick={() => setViewOnceIntent(value => !value)} aria-label="Toggle View Once"><span /></button></div>{viewOnceIntent && <label className="view-duration-select">Viewing duration<select value={viewDurationSeconds} onChange={event => setViewDurationSeconds(Number(event.target.value))}><option value={0}>Until closed</option><option value={5}>5 seconds</option><option value={10}>10 seconds</option><option value={30}>30 seconds</option></select></label>}<button className="primary-btn" onClick={() => void sendFile(pendingFile, { viewOnce: viewOnceIntent, viewDurationSeconds })} disabled={uploading}>{uploading ? `Uploading ${uploadProgress}%` : 'Send photo'}<Send size={16} /></button><p className="privacy-warning"><ShieldCheck size={14} /> View Once media is private and is not saved in shared media.</p></div></div>}
  </main>
}

